Automated Stock Deduction</p></div><div class="p-2.5 rounded-lg bg-black/40 border border-gray-800/80"><span class="text-[#FF5E00] font-semibold flex items-center gap-1.5"><i class="fa-solid fa-users"></i> People &amp; Partners</span><p class="text-[11px] text-gray-400 mt-1">Suppliers, Customers &amp; Staff</p></div><div class="p-2.5 rounded-lg bg-black/40 border border-gray-800/80"><span class="text-[#FF5E00] font-semibold flex items-center gap-1.5"><i class="fa-solid fa-file-invoice-dollar"></i> Reports &amp; Analytics</span><p class="text-[11px] text-gray-400 mt-1">Printable Jasper Receipts &amp; Logs</p></div></div></div><div class="px-6 py-3.5 border-t border-gray-800/90 bg-[#141419] flex items-center justify-between text-xs text-gray-400"><div class="flex items-center gap-2"><i class="fa-solid fa-circle-info text-[#FF5E00]"></i><span class="">Press <kbd class="px-1.5 py-0.5 bg-black/60 rounded border border-gray-700 text-gray-300 font-mono text-[10px]">Esc</kbd> or click outside to dismiss</span></div><button class="px-4 py-1.5 rounded-full bg-[#FF5E00] hover:bg-[#FF7315] text-white font-semibold transition-colors shadow-[0_0_12px_rgba(255,94,0,0.4)]" onclick="closePosModal()">Close Preview</button></div></div></div>
<script>
  const aquilaSlides = Array.from(document.querySelectorAll('.aquila-thumb-btn img')).map((image) => ({
    src: image.src,
    title: image.alt || image.closest('button').textContent.trim(),
  }));

  const posSlides = Array.from(document.querySelectorAll('.pos-thumb-btn img')).map((image) => ({
    src: image.src,
    title: image.alt || image.closest('button').textContent.trim(),
  }));

  function showModal(id) {
    const modal = document.getElementById(id);
    if (!modal) return;

    modal.classList.remove('hidden');
    modal.classList.add('flex');
    modal.setAttribute('aria-hidden', 'false');
    document.body.classList.add('overflow-hidden');
  }

  function hideModal(id) {
    const modal = document.getElementById(id);
    if (!modal) return;

    modal.classList.add('hidden');
    modal.classList.remove('flex');
    modal.setAttribute('aria-hidden', 'true');

    if (!document.querySelector('[role="dialog"].flex')) {
      document.body.classList.remove('overflow-hidden');
    }
  }

  function openAquilaModal() {
    showModal('aquilaModal');
    selectAquilaSlide(Number(document.getElementById('aquilaModal').dataset.currentIndex || 0));
  }

  function closeAquilaModal() {
    hideModal('aquilaModal');
  }

  function selectAquilaSlide(index) {
    if (!aquilaSlides.length) return;

    const modal = document.getElementById('aquilaModal');
    const image = document.getElementById('aquilaGalleryMainImg');
    const title = document.getElementById('aquilaSlideTitle');
    const counter = document.getElementById('aquilaSlideCounter');
    const thumbnails = document.querySelectorAll('.aquila-thumb-btn');
    const currentIndex = (index + aquilaSlides.length) % aquilaSlides.length;

    modal.dataset.currentIndex = currentIndex;
    image.src = aquilaSlides[currentIndex].src;
    title.textContent = aquilaSlides[currentIndex].title;
    counter.textContent = `(${currentIndex + 1} of ${aquilaSlides.length})`;

    thumbnails.forEach((thumbnail, thumbnailIndex) => {
      thumbnail.classList.toggle('border-2', thumbnailIndex === currentIndex);
      thumbnail.classList.toggle('border-orange-500', thumbnailIndex === currentIndex);
      thumbnail.classList.toggle('shadow-[0_0_10px_#FF5E00]', thumbnailIndex === currentIndex);
      thumbnail.classList.toggle('border', thumbnailIndex !== currentIndex);
      thumbnail.classList.toggle('border-gray-800', thumbnailIndex !== currentIndex);
    });
  }

  function prevAquilaSlide() {
    const current = Number(document.getElementById('aquilaModal').dataset.currentIndex || 0);
    selectAquilaSlide(current - 1);
  }

  function nextAquilaSlide() {
    const current = Number(document.getElementById('aquilaModal').dataset.currentIndex || 0);
    selectAquilaSlide(current + 1);
  }

  function openPosModal() {
    showModal('posModal');
    selectPosSlide(Number(document.getElementById('posModal').dataset.currentIndex || 0));
  }

  function closePosModal() {
    hideModal('posModal');
  }

  function selectPosSlide(index) {
    if (!posSlides.length) return;

    const modal = document.getElementById('posModal');
    const image = document.getElementById('posGalleryMainImg');
    const title = document.getElementById('posSlideTitle');
    const counter = document.getElementById('posSlideCounter');
    const thumbnails = document.querySelectorAll('.pos-thumb-btn');
    const currentIndex = (index + posSlides.length) % posSlides.length;

    modal.dataset.currentIndex = currentIndex;
    image.src = posSlides[currentIndex].src;
    title.textContent = posSlides[currentIndex].title;
    counter.textContent = `(${currentIndex + 1} of ${posSlides.length})`;

    thumbnails.forEach((thumbnail, thumbnailIndex) => {
      thumbnail.classList.toggle('border-2', thumbnailIndex === currentIndex);
      thumbnail.classList.toggle('border-orange-500', thumbnailIndex === currentIndex);
      thumbnail.classList.toggle('shadow-[0_0_10px_#FF5E00]', thumbnailIndex === currentIndex);
      thumbnail.classList.toggle('border', thumbnailIndex !== currentIndex);
      thumbnail.classList.toggle('border-gray-800', thumbnailIndex !== currentIndex);
    });
  }

  function prevPosSlide() {
    const current = Number(document.getElementById('posModal').dataset.currentIndex || 0);
    selectPosSlide(current - 1);
  }

  function nextPosSlide() {
    const current = Number(document.getElementById('posModal').dataset.currentIndex || 0);
    selectPosSlide(current + 1);
  }

  document.addEventListener('keydown', function(event) {
    if (event.key === 'Escape') {
      closeAquilaModal();
      closePosModal();
    }

    const aquilaOpen = document.getElementById('aquilaModal').classList.contains('flex');
    const posOpen = document.getElementById('posModal').classList.contains('flex');

    if (event.key === 'ArrowLeft' && aquilaOpen) prevAquilaSlide();
    if (event.key === 'ArrowRight' && aquilaOpen) nextAquilaSlide();
    if (event.key === 'ArrowLeft' && posOpen) prevPosSlide();
    if (event.key === 'ArrowRight' && posOpen) nextPosSlide();
  });
</script>
<!-- END: AQUILA Hardware Architecture Modal -->


</body></html>
